module TopModule(
    input clk,
    input resetn,
    input x,
    input y,
    output logic f,
    output logic g
);

typedef enum logic [3:0] { A, F1, S0, S1, S2, G1, G2, GPERM, GZERO } state_t;
state_t state, next;

always_ff @(posedge clk) begin
    if (!resetn) state <= A;
    else state <= next;
end

always_comb begin
    f = 1'b0;
    g = 1'b0;
    next = state;
    case (state)
        A: begin
            if (resetn) next = F1;
        end
        F1: begin
            f = 1'b1;
            next = S0;
        end
        S0: begin
            if (x) next = S1;
            else next = S0;
        end
        S1: begin
            if (x) next = S1;
            else next = S2;
        end
        S2: begin
            if (x) next = G1;
            else next = S0;
        end
        G1: begin
            g = 1'b1;
            if (y) next = GPERM;
            else next = G2;
        end
        G2: begin
            g = 1'b1;
            if (y) next = GPERM;
            else next = GZERO;
        end
        GPERM: begin
            g = 1'b1;
            next = GPERM;
        end
        GZERO: begin
            next = GZERO;
        end
        default: next = A;
    endcase
end

endmodule

